import { rs } from "./rs";
import { Button } from "./button";
import { Icon } from "./icons";
import { CanvasControls } from "./canvas-controls";
import { Dialog, DialogTitle } from "./dialog";

export interface ViewerImage { src: string; alt: string; caption?: string }
