  },
  dot: {
    width: {
      default: "1rem",
      [mq.phone]: "1.375rem",
    },
    height: {
      default: "1rem",
      [mq.phone]: "1.375rem",
    },
    borderRadius: "50%",
    borderWidth: 1.5,
    borderStyle: "solid",
    borderColor: {
      default: vlak.controlBorder,
      [mq.forcedColors]: "CanvasText",
    },
    position: "relative",
    flexShrink: 0,
    boxSizing: "border-box",
  },
  on: {
    borderColor: {
      default: vlak.ink,
      [mq.forcedColors]: "Highlight",
    },
  },
  fill: {
    position: "absolute",
    inset: {
      default: "0.1875rem",
      [mq.phone]: "0.3125rem",
    },
    borderRadius: "50%",
    backgroundColor: {
      default: vlak.ink,
