    pointerEvents: "none",
  },
  thumb: {
    position: "absolute",
    top: "50%",
    transform: "translate(-50%, -50%)",
    width: {
      default: "0.875rem",
      [mq.phone]: "1.375rem",
    },
    height: {
      default: "0.875rem",
      [mq.phone]: "1.375rem",
    },
