    },
    backgroundColor: vlak.paper,
    borderWidth: 1.5,
    borderStyle: "solid",
    borderColor: vlak.ink,
    boxSizing: "border-box",
    pointerEvents: "none",
  },
  /** Keyboard focus on the hidden range paints a ring on the thumb. */
  thumbFocused: {
    outlineWidth: 2,
    outlineStyle: "solid",
    outlineColor: vlak.ink,
    outlineOffset: 2,
  },
  range: {
    position: "absolute",
