import { vlak } from "./tokens.stylex";
import { rs } from "./rs";

const styles = stylex.create({
  kbd: {
    fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
    fontSize: "0.6875rem",
    fontWeight: 500,
    color: vlak.gray,
