});

/* ── kbd: generated from packages/react/src/components/kbd.tsx ── */
.rs-kbd{font-family:ui-monospace, SFMono-Regular, Menlo, monospace;font-size:0.6875rem;font-weight:500;color:var(--text-secondary);background-color:var(--bg);border-width:1px;border-style:solid;border-color:var(--divider);border-bottom-width:2px;border-radius:var(--radius-sm);padding-block:2px;padding-inline:0.375rem;line-height:1.2}
