          {type === "datetime-local" && <Button type="button" className={done.className} style={done.style} onClick={() => { if (draftIssue) setPanelError(draftIssue); else choose(draftValue); }}>Done</Button>}
        </div>
      </>}
    </div>
  </div>;
});

